SELECT REL_ID relId, REL_TYPE relType, REL_NAME relName, REL_NUMBER relNumber, TRAN_TYPE tranType, TRADE_ORG tradeOrg, TRADE_AMOUNT tradeAmount, MAJOR_TRADE majorTrade FROM ins_tra_business WHERE 1=1
and REL_ID = #{pid}
UNION SELECT REL_ID relId, REL_TYPE relType, REL_NAME relName, REL_NUMBER relNumber, TRAN_TYPE tranType, TRADE_ORG tradeOrg, TRADE_AMOUNT tradeAmount, MAJOR_TRADE majorTrade FROM ins_tra_investment WHERE 1=1
and REL_ID = #{pid}
UNION SELECT REL_ID relId, REL_TYPE relType, REL_NAME relName, REL_NUMBER relNumber, TRAN_TYPE tranType, TRADE_ORG tradeOrg, TRADE_AMOUNT tradeAmount, MAJOR_TRADE majorTrade FROM ins_tra_funds WHERE 1=1
and REL_ID = #{pid}
UNION SELECT REL_ID relId, REL_TYPE relType, REL_NAME relName, REL_NUMBER relNumber, TRAN_TYPE tranType, TRADE_ORG tradeOrg, TRADE_AMOUNT tradeAmount, MAJOR_TRADE majorTrade FROM ins_tra_interest WHERE 1=1
and REL_ID = #{pid}
UNION SELECT REL_ID relId, REL_TYPE relType, REL_NAME relName, REL_NUMBER relNumber, TRAN_TYPE tranType, TRADE_ORG tradeOrg, TRADE_AMOUNT tradeAmount, MAJOR_TRADE majorTrade FROM ins_tra_service WHERE 1=1
and REL_ID = #{pid}

SELECT sum(coalesce(t.Contract_Amount,0)) res FROM (
    select sum(coalesce(Contract_Amount,0)) Contract_Amount
    from
    ins_tra_business
    where
    STATUS= '6'
    and DELFLAG_ = '1'
    
        AND IS_ACCUMULATED != '1'
    
    and DATE_FORMAT(TRAN_DATE, '%Y') = #{year}
    and is_cash_subscribe = '1'
    
        and REL_ID IN (
            SELECT pid FROM bus_rel_org WHERE mem_group = (SELECT mem_group FROM bus_rel_org WHERE pid = #{relId}) AND pid != #{relId}
            union ALL
            SELECT pid FROM bus_rel_org WHERE pid = #{relId})
        
            and Contract_Amount  >  500
        
    
    
        and REL_ID = #{relId}
        and REL_TYPE = #{relType}
        
            and Contract_Amount  >  500
        
    
    
        and REL_ID = #{relId}
        and REL_TYPE = #{relType}
        
            and Contract_Amount  > 50
        
    
    
        AND (Major_Type is NULL OR Major_Type = 2)
    
    
        AND Tra_sub_Name = #{traSubName}
    
    /*GROUP BY CONTRACT_NO
    HAVING COUNT(CONTRACT_NO) = 1*/
    ) t order by res limit 10

        SELECT TRAN_DATE as tranDate,REL_NAME as relName,is_HoldingSubsidiary as isHoldingSubsidiary ,
        PRODUCT_NAME as productName,TRADE_AMOUNT as tradeAmount, Contract_Amount as contractAmount,
        TRADE_SUBJECT as tradeSubject
        from ins_tra_business
        WHERE 1=1
        
            and DATE_FORMAT(TRAN_DATE, '%Y')=#{year}
        

        
            and QUARTER(TRAN_DATE)=#{quarter}
        

        
            and Tra_sub_Name=#{subOrg}
        
         and DELFLAG_=1
        and STATUS=6

SELECT TRAN_DATE as tranDate,REL_NAME as relName,is_HoldingSubsidiary as isHoldingSubsidiary , PRODUCT_NAME as productName,TRADE_AMOUNT as tradeAmount, Contract_Amount as contractAmount, TRADE_SUBJECT as tradeSubject from ins_tra_business WHERE 1=1 and (DATE_FORMAT(TRAN_DATE, '%Y') < #{year} or (DATE_FORMAT(TRAN_DATE, '%Y') = #{year} and QUARTER(TRAN_DATE) < #{quarter})) and (date_part('year',BUS_END_TIME) > #{year} or (date_part('year',BUS_END_TIME) = #{year} and QUARTER(BUS_END_TIME) >= #{quarter}))
and Tra_sub_Name=#{subOrg}
and DELFLAG_=1 and STATUS=6

SELECT sum(coalesce(t.Contract_Amount,0)) FROM (
select sum(coalesce(Contract_Amount,0)) Contract_Amount
from
ins_tra_business
where
STATUS in ('1','3','4')
and DELFLAG_ = '1'
AND (IS_ACCUMULATED is NULL OR IS_ACCUMULATED = '0')
and DATE_FORMAT(TRAN_DATE, '%Y') = #{year}
and is_cash_subscribe = '1'

    and REL_ID IN (
    SELECT pid FROM bus_rel_org WHERE mem_group = (SELECT mem_group FROM bus_rel_org WHERE pid = #{relId})
    AND pid != #{relId}
    union ALL
    SELECT pid FROM bus_rel_org WHERE pid = #{relId})
    and Contract_Amount  >  500
    and REL_TYPE = #{relType}


    and REL_ID = #{relId}
    and REL_TYPE = #{relType}
    and Contract_Amount  >  500


    and REL_ID = #{relId}
    and REL_TYPE = #{relType}
    and Contract_Amount  >  50


    AND Tra_sub_Name = #{traSubName}

AND (Major_Type is NULL OR Major_Type = 2)
/*GROUP BY CONTRACT_NO
HAVING COUNT(CONTRACT_NO) = 1*/
) t

