UPDATE ins_tra_business
SET IS_ACCUMULATED = '1'
WHERE
STATUS = '6'
AND (IS_ACCUMULATED is NULL OR IS_ACCUMULATED = '0')
AND DELFLAG_ = '1'
AND YEAR ( TRAN_DATE ) = #{year}
AND is_cash_subscribe = '1'

    and REL_ID IN (
    SELECT pid FROM bus_rel_org WHERE mem_group = (SELECT mem_group FROM bus_rel_org WHERE pid = #{relId})
    AND pid != #{relId}
    union ALL
    SELECT pid FROM bus_rel_org WHERE pid = #{relId})
    and Contract_Amount  >  500


    AND REL_ID = #{relId}
    AND REL_TYPE = #{relType}
    AND Contract_Amount> 500


    AND REL_ID = #{relId}
    AND REL_TYPE = #{relType}
    AND Contract_Amount> 50


    AND Tra_sub_Name = #{traSubName}

AND (Major_Type is NULL OR Major_Type = 2)

 update ins_tra_business
set TRAN_DATE = #{contractDate},TRADE_AMOUNT = #{relTrandeAmount},STATUS = '6'
Where pid = #{pid}

mapper.select:
SELECT itb.REL_ID as relId, itb.REL_NAME as relName, itb.TRAN_TYPE as tranType, itb.REMARK as remark, itb.TRAN_DATE as tranDate, itb.TRA_SUB_NAME as traSubName, itb.manager_org as managerOrg, SUM(itb.prac_trade_amount) over(partition by rel_id,tran_type,bus_type
,manager_org
) as contractAmount, itb.BUS_TYPE AS tranOverView FROM INS_TRA_BUSINESS itb WHERE itb.STATUS IN ('6','7','10') AND itb.DELFLAG_ = '1' and itb.tran_type is not null and itb.prac_trade_amount is not null and itb.bus_type is not null
and to_char(itb.TRAN_DATE,'YYYY-MM-DD') BETWEEN #{staTime} AND #{endTime}

from ins_tra_business where 1=1 AND data_version = 'E2.0' and PRAC_TRADE_AMOUNT IS null and STATUS != '9'
AND CONTRACT_NO = #{contractNo}
AND REL_NUMBER = #{relNumber}
AND DELFLAG_ = '1'

select CONTRACT_NO, Contract_Amount, SUM(PRAC_TRADE_AMOUNT) as PRAC_TRADE_AMOUNT from ins_tra_business where 1=1
AND CONTRACT_NO = #{contractNo}
GROUP BY CONTRACT_NO, Contract_Amount

        SELECT *
        FROM ins_tra_business
        WHERE
        1=1
            AND data_version = 'E2.0'
        
            and  contract_no like
            CONCAT(CONCAT('%', #{contractNo}), '%')
        
        
            and REL_NUMBER = #{relNumber}
        
        
            and rel_Name like
            CONCAT(CONCAT('%', #{relName}), '%')
        
        
            and bus_type = #{busType}
        
        
            and DATE_FORMAT(contract_date,'%Y-%m-%d') >= #{startTranDate}
        
        
            and DATE_FORMAT(contract_date,'%Y-%m-%d') <= #{endTranDate}
        
        
            and consider_Type = #{considerType}
        
        
            and major_Trade=#{majorTrade}
        
        
            and status = #{status}
        
        
            and ( AMEND_ID IN (SELECT staff_code_ FROM sys_staff WHERE  dept_code_ = #{deptCode}) or AMEND_ID IS NULL)
        
        
            and subStr(created_time_,1,10) = #{createTimeString}
        
        
            and data_sources = #{dataSources}
        
        
            

            
            
                OR AMEND_NAME = 'System'
                OR AMEND_NAME IS NULL
            
        
        and ((DELFLAG_ = '1'))
        ORDER BY MODIFIED_TIME_ DESC,CREATED_TIME_ DESC

SELECT * FROM ins_tra_business WHERE 1=1
and TRANS_NUM = #{transNum}
and ((DELFLAG_ = '1')) ORDER BY MODIFIED_TIME_ DESC
